def fp(s):return (s.st_dev,s.st_ino,s.st_mode,s.st_nlink,s.st_size,s.st_mtime_ns,s.st_ctime_ns)
def read(p,cap):
 assert str(p.resolve())==str(p)
 a=p.lstat();assert stat.S_ISREG(a.st_mode) and a.st_nlink==1 and a.st_size<=cap
 fd=os.open(p,os.O_RDONLY|os.O_NOFOLLOW|os.O_NONBLOCK|os.O_CLOEXEC)
 try:
  assert fp(os.fstat(fd))==fp(a)
  chunks=[];size=0
  while True:
   b=os.read(fd,65536)
   if not b:break
   size+=len(b);assert size<=a.st_size;chunks.append(b)
  assert size==a.st_size and fp(os.fstat(fd))==fp(a)==fp(p.lstat())
  return b"".join(chunks)
 finally:os.close(fd)
def put(p,b):
 with p.open("xb") as f:f.write(b);f.flush();os.fsync(f.fileno())
 assert read(p,1048576)==b
for n,s in CODES.items():put(P/n,s.encode())
rows=[]
for t in PROV["closed_terminal_metadata"]:
 src=pathlib.Path(t["archive_path"]);data=read(src,1048576)
 assert len(data)==t["available_end"]==t["status"]["bytes_stored"]
 assert hashlib.sha256(data[t["offset"]:t["next_offset"]]).hexdigest()==t["chunk_sha256"]
 dest=T/(t["name"]+".original.log");put(dest,data)
 rows.append({"path":str(dest.relative_to(R)),"bytes":len(data),"sha256":hashlib.sha256(data).hexdigest(),"origin":{"host":"mac","path":str(src)}})
put(T/"terminal-origin-index.json",(json.dumps(rows,sort_keys=True,indent=2)+"\n").encode())
put(T/"producer-and-tool-provenance.json",(json.dumps(PROV,sort_keys=True,indent=2)+"\n").encode())
print(json.dumps({"status":"CLOSED_PRODUCERS_AND_ALL15_FULL_TERMINALS_PRESERVED","producers":len(CODES),"terminals":len(rows),"terminal_bytes":sum(x["bytes"] for x in rows),"ephemeral_urls_not_saved":True},sort_keys=True))
